/// <summary>
/// PaffH 06.12.21
/// controler for 'get privilege info in batch mode'
/// </summary>
class NDXPrivilegeInfoGetBatchController
    extends SysOperationServiceController
{
}

Method.Source:
public static NDXPrivilegeInfoGetBatchController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::ReliableAsynchronous)
{
    NDXPrivilegeInfoGetBatchController controller;
    controller = new NDXPrivilegeInfoGetBatchController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// PaffH 06.12.21
/// called from MenuItem
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    NDXPrivilegeInfoGetBatchController controller;
    controller = NDXPrivilegeInfoGetBatchController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}
